package net.civeira.phylax.features.access.consentpurpose.domain.valueobject;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.common.exception.ConstraintException;

class DescriptionVOUnitTest {

  /**
   * @autogenerated ValueObjectGenerator
   */
  @Test
  @DisplayName("Test value object contruction for property description of consent purpose ")
  void test_description_v_o_builder() {
    Assertions.assertThrows(ConstraintException.class, () -> DescriptionVO.tryFrom(null));
    Assertions.assertEquals("one", DescriptionVO.from("one").getDescription());
    Object falingInstance = new Object() {};
    Assertions.assertThrows(ConstraintException.class, () -> DescriptionVO.tryFrom(falingInstance));
    Assertions.assertEquals("[" + "one" + "]", DescriptionVO.from("one").toString());
  }
}
